-- 冒險世界示範章節種子資料
SET XACT_ABORT ON;

BEGIN TRY
    BEGIN TRANSACTION;

    -- 重跑時沿用既有版本 UUID，不改寫玩家存檔引用。
    DECLARE @SeedVersionNo NVARCHAR(50);
    SELECT @SeedVersionNo = NULLIF(CurrentVersionNo, N'')
    FROM dbo.AdventureWorlds WITH (UPDLOCK, HOLDLOCK)
    WHERE WorldNo = N'DEMO_TOWN';
    IF @SeedVersionNo IS NULL
        SELECT TOP (1) @SeedVersionNo = VersionNo
        FROM dbo.AdventureVersions
        WHERE WorldNo = N'DEMO_TOWN'
        ORDER BY Id;
    IF @SeedVersionNo IS NULL
        SET @SeedVersionNo = N'VER_' + REPLACE(CONVERT(NVARCHAR(36), NEWID()), N'-', N'');

    IF NOT EXISTS (SELECT 1 FROM dbo.AdventureWorlds WHERE WorldNo = N'DEMO_TOWN')
    BEGIN
        INSERT INTO dbo.AdventureWorlds (WorldNo, WorldName, Description, IsOpen, CurrentVersionNo, Remark)
        VALUES (N'DEMO_TOWN', N'穿越至陌生小鎮', N'員工本人抵達未知故事世界，遇見由同事映射的人物，尋找立足方式及世界異常的線索。', 0, N'', N'預設示範世界');
    END;

    IF NOT EXISTS (SELECT 1 FROM dbo.AdventureDrafts WHERE WorldNo = N'DEMO_TOWN')
    BEGIN
        INSERT INTO dbo.AdventureDrafts (WorldNo, Revision, Content, UpdatedBy, Remark)
