 "buy_pickaxe", "name": "購買工匠鐵鎬", "description": "花費 25 金幣購買一把堅固的鐵鎬。", "cost": {"gold": 25, "ep": 0, "turn": 0}, "effects": [{"type": "add_item", "item_id": "artisan_pickaxe", "count": 1}]}], "objects": []}, "suburb_workshop": {"id": "suburb_workshop", "name": "鎮郊工坊", "description": "位於小鎮邊緣的鐵匠工坊，叮叮噹噹的敲擊聲不絕於耳，後方連接險峻山道。", "exits": ["town_square"], "travel_cost": {"ep": 5}, "activities": [{"id": "work_workshop", "name": "工坊打工", "description": "協助搬運礦石與拉風箱，消耗 20 精力與 1 回合，賺取 30 金幣。", "cost": {"ep": 20, "turn": 1, "gold": 0}, "effects": [{"type": "modify_stat", "stat": "gold", "value": 30}]}, {"id": "gather_mountain", "name": "後山採集", "description": "前往後山林地採集原生草藥與礦物，消耗 15 精力與 1 回合。", "cost": {"ep": 15, "turn": 1, "gold": 0}, "flow_id": "flow_gather_mountain"}], "objects": [{"id": "workshop_secret_trail", "name": "後山隱密山徑", "description": "草叢掩蓋下的一條狹窄山道，似乎能繞過前方的守衛關卡。", "flow_id": "flow_secret_trail"}]}, "guard_post": {"id": "guard_post", "name": "守衛關卡", "description": "通往下一個區域的必經隘口，厚實的木製柵欄與石堡封鎖了道路，守衛嚴陣以待。", "exits": ["town_square"], "travel_cost": {"ep": 5}, "activities": [], "objects": []}}, "npcs": {"guard_captain": {"id": "guard_captain", "slot_name": "守衛長", "mapped_employee_id": "", "fallback_character": {"name": "杜恩", "title": "鐵面守衛長", "bio": "嚴厲恪守職責的關卡守衛長，重視秩序與法規。", "photo_file": ""}, "schedule": {"morning": "guard_post", "noon": "guard_post", "dusk": "guard_post", "night": "cozy_inn"}, "initial_affinity": 0, "dialogue_flow_id": "flow_guard_captain"}, "innkeeper": {"id": "innkeeper", "slot_name": "旅店老闆", "mapped_employee_id": "", "fallback_character": {"name": "瑪莎", "title": "熱心老闆娘", "bio": "溫和風趣的旅店主人，知道許多小鎮各處的祕密與八卦。", "photo_file": ""}, "schedule": {"morning": "cozy_inn", "noon": "cozy_inn", "dusk": "cozy_inn", "night": "cozy_inn"}, "initial_affinity": 10, "dialogue_flow_id": "flow_innkeeper"}, "merchant": {"id": "merchant", "slot_name": "熱心商人", "mapped_employee_id": "", "fallback_character": {"name": "羅倫斯", "title": "行商", "bio": "四處遊歷的商人，手裡總有些稀奇古怪的小玩意。", "photo_file": ""}, "schedule": {"morning": "general_store", "noon": "town_square", "dusk": "general_store", "night": "cozy_inn"}, "initial_affinity": 0, "dialogue_flow_id": "flow_merchant"}, "artisan": {"id": "artisan", "slot_name": "老工匠", "mapped_employee_id": "", "fallback_character": {"name": "奧古斯特", "title": "老工匠", "bio": "沉默寡言但技藝高超的鐵匠兼學者，對古老符文略懂一二。", "photo_file": ""}, "schedule": {"morning": "suburb_workshop", "noon": "suburb_workshop", "dusk": "suburb_workshop", "night": "suburb_workshop"}, "initial_affinity": 0, "dialogue_flow_id": "flow_artisan"}}, "items": {"travel_ration": {"id": "travel_ration", "name": "行囊口糧", "type": "consumable", "description": "乾燥的乾糧與燻肉，食用可迅速恢復 30 點精力。", "effects": [{"type": "modify_stat", "stat": "ep", "value": 30}], "gift_affinity": 5}, "worn_dagger": {"id": "worn_dagger", "name": "磨損匕首", "type": "weapon", "description": "穿越時帶在身上的隨身小刀，雖然有些磨損但依舊鋒利。攻擊力 +5。", "modifiers": {"atk": 5, "def": 0}, "gift_affinity": 5}, "weird_coin": {"id": "weird_coin", "name": "古怪金幣", "type": "misc", "description": "表面刻著非同尋常花紋的重金幣，在小鎮上能作為貴重通貨流通。", "gift_affinity": 15}, "mayor_letter": {"id": "mayor_letter", "name": "鎮長介紹信", "type": "misc", "description": "由鎮上名望人士引薦的親筆信函，關卡守衛見信即放行。", "gift_affinity": 0}, "wild_herb": {"id": "wild_herb", "name": "野草草藥", "type": "consumable", "description": "小鎮後山採集的藥草，能包紮止血，恢復 35 點生命。", "effects": [{"type": "modify_stat", "stat": "hp", "value": 35}], "gift_affinity": 10}, "artisan_pickaxe": {"id": "artisan_pickaxe", "name": "工匠鐵鎬", "type": "weapon", "description": "精鋼打造的重鐵鎬，既是採集工具也能作為沉重兵器。攻擊力 +8。", "modifiers": {"atk": 8, "def": 0}, "gift_affinity": 10}, "guard_permit": {"id": "guard_permit", "name": "守衛通行證", "type": "misc", "description": "繳納通行規費後取得的正式過關印信。", "gift_affinity": 0}, "unknown_fragment": {"id": "unknown_fragment", "name": "未知碎片", "type": "misc", "description": "在隱密山道深處拾得的發光石質碎片，刻印著穿越時隱約見過的幾何符紋。", "gift_affinity": 25}}, "quests": {"settling_in": {"id": "settling_in", "name": "初來乍到", "auto_start": true, "description": "穿越到未知小鎮，探索周邊環境並與居民交談，確認自己目前的處境。"}, "pass_the_gate": {"id": "pass_the_gate", "name": "通行之路", "auto_start": true, "description": "小鎮對外出口被守衛關卡封鎖，需尋找方法前往下一個區域（解法：繳納過路費／獲取引薦信／尋找替代山道）。"}, "anomaly_echoes": {"id": "anomaly_echoes", "name": "異常回響", "auto_start": false, "description": "小鎮周邊存在不明的符文碎片與空間擾動，調查這起異常與穿越之間的關聯。"}}, "enemies": {"mountain_beast": {"id": "mountain_beast", "name": "後山兇惡野獸", "hp": 40, "atk": 12, "def": 3, "agility": 9}, "drunk_brawler": {"id": "drunk_brawler", "name": "醉酒挑釁者", "hp": 35, "atk": 10, "def": 2, "agility": 6}}, "flowcharts": {"flow_guard_captain": {"id": "flow_guard_captain", "name": "守衛長對話", "nodes": {"start": {"type": "start", "next_node_id": "check_passed"}, "check_passed": {"type": "condition", "condition": {"field": "flag.gate_passed", "op": "==", "value": true}, "next_node_true": "already_passed", "next_node_false": "greet"}, "already_passed": {"type": "narrative", "speaker": "守衛長", "text": "「你的通行資格已經登記過了，前面的道路隨時為你開放，旅途小心。」", "next_node_id": "end_normal"}, "greet": {"type": "narrative", "speaker": "守衛長", "text": "「站住！前方為管制區域。沒有合法通行手續或身分證明，任何人不得擅自通過。」", "next_node_id": "choice_gate"}, "choice_gate": {"type": "choice", "choices": [{"id": "pay_toll", "label": "【繳交規費】支付 80 金幣辦理正式通行手續", "condition": {"field": "gold", "op": ">=", "value": 80}, "cost": {"gold": 80}, "next_node_id": "toll_success"}, {"id": "show_letter", "label": "【出示信函】遞交旅店老闆娘轉交的《鎮長介紹信》", "condition": {"field": "item.mayor_letter", "op": ">=", "value": 1}, "next_node_id": "letter_success"}, {"id": "ask_about_gate", "label": "詢問通過關卡的規定與理由", "next_node_id": "inquire_gate"}, {"id": "leave_guard", "label": "我稍後再來（離開）", "next_node_id": "end_normal"}]}, "toll_success": {"type": "effect", "effects": [{"type": "add_item", "item_id": "guard_permit", "count": 1}, {"type": "set_flag", "flag": "gate_passed", "value": true}, {"type": "complete_quest", "quest_id": "pass_the_gate", "method_used": "toll_fee"}], "next_node_id": "toll_dialogue"}, "toll_dialogue": {"type": "narrative", "speaker": "守衛長", "text": "守衛長仔細清點了金幣，在卷宗上蓋下印章：「公事公辦，手續合格。放行！」【解法一：以金錢獲取通行資格】", "next_node_id": "ending_toll"}, "ending_toll": {"type": "end", "end_type": "game_ending", "ending_id": "cleared_by_tax", "ending_title": "正道啟程：守法公民的遠行"}, "letter_success": {"type": "effect", "effects": [{"type": "remove_item", "item_id": "mayor_letter", "count": 1}, {"type": "set_flag", "flag": "gate_passed", "value": true}, {"type": "change_affinity", "npc_id": "guard_captain", "value": 20}, {"type": "complete_quest", "quest_id": "pass_the_gate", "method_used": "recommendation"}], "next_node_id": "letter_dialogue"}, "letter_dialogue": {"type": "narrative", "speaker": "守衛長", "text": "守衛長看著介紹信上的親筆簽名，臉色微變並挺直腰桿：「原來是老闆娘保薦的貴客！失敬，請立刻通行！」【解法二：以人脈與交情順利通關】", "next_node_id": "ending_letter"}, "ending_letter": {"type": "end", "end_type": "game_ending", "ending_id": "cleared_by_network", "ending_title": "貴人引薦：深受信賴的同袍"}, "inquire_gate": {"type": "narrative", "speaker": "守衛長", "text": "「近來外界頻生異常，鎮長下令嚴防流竄。要通過，要嘛繳納 80 金幣重稅登記，要嘛具備在地名望人士的親筆引薦，沒有第三條路！」", "next_node_id": "choice_gate"}, "end_normal": {"type": "end", "end_type": "return_to_exploration"}}}, "flow_innkeeper": {"id": "flow_innkeeper", "name": "旅店老闆娘對話", "nodes": {"start": {"type": "start", "next_node_id": "greet_inn"}, "greet_inn": {"type": "narrative", "speaker": "旅店老闆娘", "text": "「哎呀，瞧你一臉茫然的樣子，剛來小鎮吧？若是累了隨時能在這打尖歇歇腳。」", "next_node_id": "choice_inn"}, "choice_inn": {"type": "choice", "choices": [{"id": "ask_help", "label": "詢問是否需要幫忙（好感委託）", "condition": {"field": "flag.inn_help_done", "op": "!=", "value": true}, "next_node_id": "inn_quest_offer"}, {"id": "submit_herb", "label": "遞交採集到的 2 包【野草草藥】幫忙旅店", "condition": {"all": [{"field": "flag.inn_help_accepted", "op": "==", "value": true}, {"field": "flag.inn_help_done", "op": "!=", "value": true}, {"field": "item.wild_herb", "op": ">=", "value": 2}]}, "next_node_id": "inn_submit_herb"}, {"id": "brawler_event", "label": "調查角落鬧事的醉漢（特殊遭遇）", "condition": {"all": [{"field": "time_of_day", "op": "==", "value": "night"}, {"field": "flag.brawler_settled", "op": "!=", "value": true}]}, "next_node_id": "encounter_brawler"}, {"id": "leave_inn", "label": "只是隨便看看（離開）", "next_node_id": "end_inn"}]}, "inn_quest_offer": {"type": "effect", "effects": [{"type": "set_flag", "flag": "inn_help_accepted", "value": true}], "next_node_id": "inn_quest_dialogue"}, "inn_quest_dialogue": {"type": "narrative", "speaker": "旅店老闆娘", "text": "「近來鎮上藥材短缺，若你能去鎮郊工坊後山採集 2 包野草草藥給我，我便寫封引薦信，請守衛長為你行個方便！」", "next_node_id": "end_inn"}, "inn_submit_herb": {"type": "effect", "effects": [{"type": "remove_item", "item_id": "wild_herb", "count": 2}, {"type": "add_item", "item_id": "mayor_letter", "count": 1}, {"type": "change_affinity", "npc_id": "innkeeper", "value": 30}, {"type": "set_flag", "flag": "inn_help_done", "value": true}], "next_node_id": "inn_submit_dialogue"}, "inn_submit_dialogue": {"type": "narrative", "speaker": "旅店老闆娘", "text": "「太感謝了！這些草藥解了燃眉之急。這封《鎮長介紹信》你收著，守衛長看在我的面子上絕不敢刁難你！」", "next_node_id": "end_inn"}, "encounter_brawler": {"type": "narrative", "speaker": "醉酒挑釁者", "text": "一名酒氣熏天的醉漢搖搖晃晃撞上你：「你看什麼看？！新來的鄉巴佬，想找碴嗎？！」", "next_node_id": "choice_brawler"}, "choice_brawler": {"type": "choice", "choices": [{"id": "pacify_brawler", "label": "【口才安撫】運用魅力嘗試好言相勸（魅力檢定）", "next_node_id": "check_brawler_pacify"}, {"id": "fight_brawler", "label": "【正面迎戰】直接迎頭痛擊鬧事者（進入戰鬥）", "next_node_id": "combat_brawler"}]}, "check_brawler_pacify": {"type": "check", "stat": "charisma", "base_chance": 60, "stat_coeff": 3.0, "success_node_id": "brawler_pacified", "fail_node_id": "combat_brawler"}, "brawler_pacified": {"type": "effect", "effects": [{"type": "set_flag", "flag": "brawler_settled", "value": true}, {"type": "change_affinity", "npc_id": "innkeeper", "value": 15}, {"type": "modify_stat", "stat": "gold", "value": 20}], "next_node_id": "brawler_pacified_narrative"}, "brawler_pacified_narrative": {"type": "narrative", "speaker": "旅店老闆娘", "text": "你言辭懇切、不卑不亢地化解了紛爭，醉漢自討沒趣地嘟囔著坐下。老闆娘欣喜地塞給你 20 金幣以示酬謝！", "next_node_id": "end_inn"}, "combat_brawler": {"type": "combat", "enemy_id": "drunk_brawler", "win_node_id": "brawler_won", "lose_node_id": "end_inn", "escape_node_id": "end_inn"}, "brawler_won": {"type": "effect", "effects": [{"type": "set_flag", "flag": "brawler_settled", "value": true}, {"type": "modify_stat", "stat": "gold", "value": 15}], "next_node_id": "brawler_won_narrative"}, "brawler_won_narrative": {"type": "narrative", "speaker": "系統", "text": "你俐落地制伏了鬧事醉漢，贏得旅店內一陣叫好，從對方掉落的錢袋中取得了 15 金幣！", "next_node_id": "end_inn"}, "end_inn": {"type": "end", "end_type": "return_to_exploration"}}}, "flow_merchant": {"id": "flow_merchant", "name": "商人羅倫斯對話", "nodes": {"start": {"type": "start", "next_node_id": "greet_mer"}, "greet_mer": {"type": "narrative", "speaker": "熱心商人", "text": "「嘿！遠方的旅人，只要出得起價錢，這裡什麼都有。如果手頭緊，去工坊或後山打工採集也是賺錢的好門路。」", "next_node_id": "choice_mer"}, "choice_mer": {"type": "choice", "choices": [{"id": "ask_rumors", "label": "詢問關於世界異常與穿越的傳聞", "next_node_id": "mer_rumors"}, {"id": "leave_mer", "label": "多謝提醒，我先四處看看", "next_node_id": "end_mer"}]}, "mer_rumors": {"type": "narrative", "speaker": "熱心商人", "text": "「傳聞後山深處經常有奇異的藍光閃爍，老鐵匠奧古斯特似乎在研究那些發光的石頭。若你想弄明白，不妨去拜訪他。」", "next_node_id": "end_mer"}, "end_mer": {"type": "end", "end_type": "return_to_exploration"}}}, "flow_artisan": {"id": "flow_artisan", "name": "老工匠奧古斯特對話", "nodes": {"start": {"type": "start", "next_node_id": "greet_art"}, "greet_art": {"type": "narrative", "speaker": "老工匠", "text": "老工匠放下鐵鎚，打量著你手上的裝備：「年輕人，你的腳步聲沉穩，但眼中帶著不屬於這片土地的疑惑。」", "next_node_id": "choice_art"}, "choice_art": {"type": "choice", "choices": [{"id": "show_fragment", "label": "【展示碎片】拿出在後山發現的《未知碎片》請教", "condition": {"field": "item.unknown_fragment", "op": ">=", "value": 1}, "next_node_id": "art_fragment_revealed"}, {"id": "ask_secret_trail", "label": "詢問後山山道是否真有捷徑通往外界", "next_node_id": "art_trail_hint"}, {"id": "leave_art", "label": "不打擾您工作（離開）", "next_node_id": "end_art"}]}, "art_fragment_revealed": {"type": "effect", "effects": [{"type": "complete_quest", "quest_id": "anomaly_echoes", "method_used": "fragment_studied"}, {"type": "change_affinity", "npc_id": "artisan", "value": 40}, {"type": "modify_stat", "stat": "atk", "value": 3}], "next_node_id": "art_fragment_narrative"}, "art_fragment_narrative": {"type": "narrative", "speaker": "老工匠", "text": "奧古斯特雙手顫抖接過碎片：「這…這正是古書記載的『異世之樞』殘片！你果然是穿越時空壁壘而來的行者！老夫替你的武器銘刻古老符印（攻擊+3），祝你早日找到答案。」", "next_node_id": "end_art"}, "art_trail_hint": {"type": "narrative", "speaker": "老工匠", "text": "「後山密道隱蔽而危險，若你的敏捷或智力足夠識破山霧與碎石，確實能避開前方的關卡守衛直接出關。」", "next_node_id": "end_art"}, "end_art": {"type": "end", "end_type": "return_to_exploration"}}}, "flow_gather_mountain": {"id": "flow_gather_mountain", "name": "後山採集事件", "nodes": {"start": {"type": "start", "next_node_id": "random_gather_event"}, "random_gather_event": {"type": "random", "branches": [{"weight": 6, "next_node_id": "gather_normal"}, {"weight": 4, "next_node_id": "gather_beast_encounter"}]}, "gather_normal": {"type": "effect", "effects": [{"type": "add_item", "item_id": "wild_herb", "count": 1}], "next_node_id": "gather_normal_text"}, "gather_normal_text": {"type": "narrative", "text": "你在山崖邊細心搜尋，採集到了一株新鮮的【野草草藥】。", "next_node_id": "end_gather"}, "gather_beast_encounter": {"type": "narrative", "text": "正當你撥開樹叢時，一頭低吼的【後山兇惡野獸】猛然擋在眼前！", "next_node_id": "choice_beast"}, "choice_beast": {"type": "choice", "choices": [{"id": "distract_beast", "label": "【投擲口糧】丟出《行囊口糧》引開野獸注意力（避開戰鬥）", "condition": {"field": "item.travel_ration", "op": ">=", "value": 1}, "cost": {}, "next_node_id": "beast_distracted"}, {"id": "check_agility_beast", "label": "【靈巧繞道】利用敏捷身手迅速撤退（敏捷檢定）", "next_node_id": "check_beast_escape"}, {"id": "fight_beast", "label": "【正面迎戰】拔出武器與野獸搏鬥（戰鬥）", "next_node_id": "combat_beast_node"}]}, "beast_distracted": {"type": "effect", "effects": [{"type": "remove_item", "item_id": "travel_ration", "count": 1}, {"type": "add_item", "item_id": "wild_herb", "count": 1}], "next_node_id": "beast_distracted_text"}, "beast_distracted_text": {"type": "narrative", "text": "野獸被誘人的口糧吸引過去大嚼，你趁機採下草藥悄然脫身！", "next_node_id": "end_gather"}, "check_beast_escape": {"type": "check", "stat": "agility", "base_chance": 50, "stat_coeff": 3.0, "success_node_id": "beast_escaped", "fail_node_id": "combat_beast_node"}, "beast_escaped": {"type": "narrative", "text": "你縱身一躍躍上高處岩石，野獸撲了個空，你順利甩開追擊！", "next_node_id": "end_gather"}, "combat_beast_node": {"type": "combat", "enemy_id": "mountain_beast", "win_node_id": "beast_slain", "lose_node_id": "end_gather", "escape_node_id": "end_gather"}, "beast_slain": {"type": "effect", "effects": [{"type": "add_item", "item_id": "wild_herb", "count": 2}, {"type": "modify_stat", "stat": "gold", "value": 25}], "next_node_id": "beast_slain_text"}, "beast_slain_text": {"type": "narrative", "text": "兇惡的野獸哀號倒地，你在獸穴旁拾取了 25 金幣與 2 株草藥！", "next_node_id": "end_gather"}, "end_gather": {"type": "end", "end_type": "return_to_exploration"}}}, "flow_secret_trail": {"id": "flow_secret_trail", "name": "秘密山道探索", "nodes": {"start": {"type": "start", "next_node_id": "trail_desc"}, "trail_desc": {"type": "narrative", "text": "藤蔓與落石掩映之下，露出一條極為陡峭的裂隙小徑。冷風從幽暗的石壁縫隙吹來，似乎能直接繞過前方的守衛關卡。", "next_node_id": "choice_trail"}, "choice_trail": {"type": "choice", "choices": [{"id": "check_trail_intellect", "label": "【勘查路徑】運用智力分析石層結構與地圖（智力檢定）", "next_node_id": "check_trail_int"}, {"id": "check_trail_agility", "label": "【攀登穿越】憑藉矯健身手攀上險峻裂谷（敏捷檢定）", "next_node_id": "check_trail_agi"}, {"id": "leave_trail", "label": "太危險了，先退回工坊", "next_node_id": "end_trail"}]}, "check_trail_int": {"type": "check", "stat": "intellect", "base_chance": 50, "stat_coeff": 3.0, "success_node_id": "trail_success_effect", "fail_node_id": "trail_failed"}, "check_trail_agi": {"type": "check", "stat": "agility", "base_chance": 50, "stat_coeff": 3.0, "success_node_id": "trail_success_effect", "fail_node_id": "trail_failed"}, "trail_failed": {"type": "effect", "effects": [{"type": "modify_stat", "stat": "hp", "value": -15}], "next_node_id": "trail_failed_text"}, "trail_failed_text": {"type": "narrative", "text": "一塊風化岩石突然崩碎，你摔了下來受到 15 點擦傷！只得暫時退回。", "next_node_id": "end_trail"}, "trail_success_effect": {"type": "effect", "effects": [{"type": "add_item", "item_id": "unknown_fragment", "count": 1}, {"type": "set_flag", "flag": "gate_passed", "value": true}, {"type": "complete_quest", "quest_id": "pass_the_gate", "method_used": "secret_trail"}], "next_node_id": "trail_success_text"}, "trail_success_text": {"type": "narrative", "text": "你成功穿越了後山險隘！在裂谷深處的祭壇上，你發現並拾起了一枚散發幽光的【未知碎片】！前方豁然開朗，你已徹底繞過了守衛關卡！【解法三：環境調查密道潛越】", "next_node_id": "ending_trail"}, "ending_trail": {"type": "end", "end_type": "game_ending", "ending_id": "cleared_by_secret_trail", "ending_title": "暗道潛影：掌握祕辛的探索者"}, "end_trail": {"type": "end", "end_type": "return_to_exploration"}}}}}', N'admin', N'示範草稿');
    END;

    IF NOT EXISTS (SELECT 1 FROM dbo.AdventureVersions WHERE WorldNo = N'DEMO_TOWN' AND VersionNo = @SeedVersionNo)
    BEGIN
        INSERT INTO dbo.AdventureVersions (WorldNo, VersionNo, FormatVersion, Content, PublishedBy, Remark)
        VALUES (N'DEMO_TOWN', @SeedVersionNo, 1, N'{"world_no": "DEMO_TOWN", "world_name": "穿越至陌生小鎮", "description": "員工本人抵達未知故事世界，遇見由同事映射的人物，尋找立足方式及世界異常的線索。", "start_location_id": "town_square", "safe_location_id": "cozy_inn", "traits": [{"id": "athletic", "name": "健步如飛", "modifiers": {"attributes": {"agility": 3}, "ep": 20}}, {"id": "scholarly", "name": "博聞強記", "modifiers": {"attributes": {"intellect": 3}, "gold": 30}}, {"id": "charismatic", "name": "八面玲瓏", "modifiers": {"attributes": {"charisma": 3}, "gold": 20}}, {"id": "resilient", "name": "身強體健", "modifiers": {"attributes": {"strength": 3}, "hp": 30}}], "initial_inventory": [{"item_id": "travel_ration", "count": 2, "equipped": false}, {"item_id": "worn_dagger", "count": 1, "equipped": false}], "locations": {"town_square": {"id": "town_square", "name": "鎮口廣場", "description": "陌生小鎮的核心廣場，石砌地面略帶斑駁，中央有一座乾涸的噴泉，四周人來人往。", "exits": ["cozy_inn", "general_store", "suburb_workshop", "guard_post"], "travel_cost": {"ep": 5}, "activities": [], "objects": [{"id": "fountain", "name": "乾涸噴泉", "description": "噴泉底部雕刻著奇怪的幾何紋路，隱約泛著微弱的光芒。", "effects": [{"type": "add_clue", "clue_id": "fountain_pattern", "title": "噴泉符文", "description": "噴泉底部的未知紋路，與這個世界通常的裝飾風格迥異。"}]}]}, "cozy_inn": {"id": "cozy_inn", "name": "溫暖旅店", "description": "木質調的溫馨旅店，空氣中飄散著烤麵包與麥芽酒的香氣，是旅人歇息的好地方。", "exits": ["town_square"], "travel_cost": {"ep": 5}, "activities": [{"id": "rest_inn", "name": "客棧休息", "description": "花費 10 金幣並休息 1 回合，恢復所有生命與精力。", "cost": {"gold": 10, "ep": 0, "turn": 1}, "effects": [{"type": "modify_stat", "stat": "hp", "value": 100}, {"type": "modify_stat", "stat": "ep", "value": 100}]}], "objects": []}, "general_store": {"id": "general_store", "name": "晨風雜貨舖", "description": "琳瑯滿目的貨架上擺滿了各類冒險用具、乾糧與旅行補給品。", "exits": ["town_square"], "travel_cost": {"ep": 5}, "activities": [{"id": "buy_herb", "name": "購買野草草藥", "description": "花費 15 金幣購買一包具療效的草藥。", "cost": {"gold": 15, "ep": 0, "turn": 0}, "effects": [{"type": "add_item", "item_id": "wild_herb", "count": 1}]}, {"id": "buy_pickaxe", "name": "購買工匠鐵鎬", "description": "花費 25 金幣購買一把堅固的鐵鎬。", "cost": {"gold": 25, "ep": 0, "turn": 0}, "effects": [{"type": "add_item", "item_id": "artisan_pickaxe", "count": 1}]}], "objects": []}, "suburb_workshop": {"id": "suburb_workshop", "name": "鎮郊工坊", "description": "位於小鎮邊緣的鐵匠工坊，叮叮噹噹的敲擊聲不絕於耳，後方連接險峻山道。", "exits": ["town_square"], "travel_cost": {"ep": 5}, "activities": [{"id": "work_workshop", "name": "工坊打工", "description": "協助搬運礦石與拉風箱，消耗 20 精力與 1 回合，賺取 30 金幣。", "cost": {"ep": 20, "turn": 1, "gold": 0}, "effects": [{"type": "modify_stat", "stat": "gold", "value": 30}]}, {"id": "gather_mountain", "name": "後山採集", "description": "前往後山林地採集原生草藥與礦物，消耗 15 精力與 1 回合。", "cost": {"ep": 15, "turn": 1, "gold": 0}, "flow_id": "flow_gather_mountain"}], "objects": [{"id": "workshop_secret_trail", "name": "後山隱密山徑", "description": "草叢掩蓋下的一條狹窄山道，似乎能繞過前方的守衛關卡。", "flow_id": "flow_secret_trail"}]}, "guard_post": {"id": "guard_post", "name": "守衛關卡", "description": "通往下一個區域的必經隘口，厚實的木製柵欄與石堡封鎖了道路，守衛嚴陣以待。", "exits": ["town_square"], "travel_cost": {"ep": 5}, "activities": [], "objects": []}}, "npcs": {"guard_captain": {"id": "guard_captain", "slot_name": "守衛長", "mapped_employee_id": "", "fallback_character": {"name": "杜恩", "title": "鐵面守衛長", "bio": "嚴厲恪守職責的關卡守衛長，重視秩序與法規。", "photo_file": ""}, "schedule": {"morning": "guard_post", "noon": "guard_post", "dusk": "guard_post", "night": "cozy_inn"}, "initial_affinity": 0, "dialogue_flow_id": "flow_guard_captain"}, "innkeeper": {"id": "innkeeper", "slot_name": "旅店老闆", "mapped_employee_id": "", "fallback_character": {"name": "瑪莎", "title": "熱心老闆娘", "bio": "溫和風趣的旅店主人，知道許多小鎮各處的祕密與八卦。", "photo_file": ""}, "schedule": {"morning": "cozy_inn", "noon": "cozy_inn", "dusk": "cozy_inn", "night": "cozy_inn"}, "initial_affinity": 10, "dialogue_flow_id": "flow_innkeeper"}, "merchant": {"id": "merchant", "slot_name": "熱心商人", "mapped_employee_id": "", "fallback_character": {"name": "羅倫斯", "title": "行商", "bio": "四處遊歷的商人，手裡總有些稀奇古怪的小玩意。", "photo_file": ""}, "schedule": {"morning": "general_store", "noon": "town_square", "dusk": "general_store", "night": "cozy_inn"}, "initial_affinity": 0, "dialogue_flow_id": "flow_merchant"}, "artisan": {"id": "artisan", "slot_name": "老工匠", "mapped_employee_id": "", "fallback_character": {"name": "奧古斯特", "title": "老工匠", "bio": "沉默寡言但技藝高超的鐵匠兼學者，對古老符文略懂一二。", "photo_file": ""}, "schedule": {"morning": "suburb_workshop", "noon": "suburb_workshop", "dusk": "suburb_workshop", "night": "suburb_workshop"}, "initial_affinity": 0, "dialogue_flow_id": "flow_artisan"}}, "items": {"travel_ration": {"id": "travel_ration", "name": "行囊口糧", "type": "consumable", "description": "乾燥的乾糧與燻肉，食用可迅速恢復 30 點精力。", "effects": [{"type": "modify_stat", "stat": "ep", "value": 30}], "gift_affinity": 5}, "worn_dagger": {"id": "worn_dagger", "name": "磨損匕首", "type": "weapon", "description": "穿越時帶在身上的隨身小刀，雖然有些磨損但依舊鋒利。攻擊力 +5。", "modifiers": {"atk": 5, "def": 0}, "gift_affinity": 5}, "weird_coin": {"id": "weird_coin", "name": "古怪金幣", "type": "misc", "description": "表面刻著非同尋常花紋的重金幣，在小鎮上能作為貴重通貨流通。", "gift_affinity": 15}, "mayor_letter": {"id": "mayor_letter", "name": "鎮長介紹信", "type": "misc", "description": "由鎮上名望人士引薦的親筆信函，關卡守衛見信即放行。", "gift_affinity": 0}, "wild_herb": {"id": "wild_herb", "name": "野草草藥", "type": "consumable", "description": "小鎮後山採集的藥草，能包紮止血，恢復 35 點生命。", "effects": [{"type": "modify_stat", "stat": "hp", "value": 35}], "gift_affinity": 10}, "artisan_pickaxe": {"id": "artisan_pickaxe", "name": "工匠鐵鎬", "type": "weapon", "description": "精鋼打造的重鐵鎬，既是採集工具也能作為沉重兵器。攻擊力 +8。", "modifiers": {"atk": 8, "def": 0}, "gift_affinity": 10}, "guard_permit": {"id": "guard_permit", "name": "守衛通行證", "type": "misc", "description": "繳納通行規費後取得的正式過關印信。", "gift_affinity": 0}, "unknown_fragment": {"id": "unknown_fragment", "name": "未知碎片", "type": "misc", "description": "在隱密山道深處拾得的發光石質碎片，刻印著穿越時隱約見過的幾何符紋。", "gift_affinity": 25}}, "quests": {"settling_in": {"id": "settling_in", "name": "初來乍到", "auto_start": true, "description": "穿越到未知小鎮，探索周邊環境並與居民交談，確認自己目前的處境。"}, "pass_the_gate": {"id": "pass_the_gate", "name": "通行之路", "auto_start": true, "description": "小鎮對外出口被守衛關卡封鎖，需尋找方法前往下一個區域（解法：繳納過路費／獲取引薦信／尋找替代山道）。"}, "anomaly_echoes": {"id": "anomaly_echoes", "name": "異常回響", "auto_start": false, "description": "小鎮周邊存在不明的符文碎片與空間擾動，調查這起異常與穿越之間的關聯。"}}, "enemies": {"mountain_beast": {"id": "mountain_beast", "name": "後山兇惡野獸", "hp": 40, "atk": 12, "def": 3, "agility": 9}, "drunk_brawler": {"id": "drunk_brawler", "name": "醉酒挑釁者", "hp": 35, "atk": 10, "def": 2, "agility": 6}}, "flowcharts": {"flow_guard_captain": {"id": "flow_guard_captain", "name": "守衛長對話", "nodes": {"start": {"type": "start", "next_node_id": "check_passed"}, "check_passed": {"type": "condition", "condition": {"field": "flag.gate_passed", "op": "==", "value": true}, "next_node_true": "already_passed", "next_node_false": "greet"}, "already_passed": {"type": "narrative", "speaker": "守衛長", "text": "「你的通行資格已經登記過了，前面的道路隨時為你開放，旅途小心。」", "next_node_id": "end_normal"}, "greet": {"type": "narrative", "speaker": "守衛長", "text": "「站住！前方為管制區域。沒有合法通行手續或身分證明，任何人不得擅自通過。」", "next_node_id": "choice_gate"}, "choice_gate": {"type": "choice", "choices": [{"id": "pay_toll", "label": "【繳交規費】支付 80 金幣辦理正式通行手續", "condition": {"field": "gold", "op": ">=", "value": 80}, "cost": {"gold": 80}, "next_node_id": "toll_success"}, {"id": "show_letter", "label": "【出示信函】遞交旅店老闆娘轉交的《鎮長介紹信》", "condition": {"field": "item.mayor_letter", "op": ">=", "value": 1}, "next_node_id": "letter_success"}, {"id": "ask_about_gate", "label": "詢問通過關卡的規定與理由", "next_node_id": "inquire_gate"}, {"id": "leave_guard", "label": "我稍後再來（離開）", "next_node_id": "end_normal"}]}, "toll_success": {"type": "effect", "effects": [{"type": "add_item", "item_id": "guard_permit", "count": 1}, {"type": "set_flag", "flag": "gate_passed", "value": true}, {"type": "complete_quest", "quest_id": "pass_the_gate", "method_used": "toll_fee"}], "next_node_id": "toll_dialogue"}, "toll_dialogue": {"type": "narrative", "speaker": "守衛長", "text": "守衛長仔細清點了金幣，在卷宗上蓋下印章：「公事公辦，手續合格。放行！」【解法一：以金錢獲取通行資格】", "next_node_id": "ending_toll"}, "ending_toll": {"type": "end", "end_type": "game_ending", "ending_id": "cleared_by_tax", "ending_title": "正道啟程：守法公民的遠行"}, "letter_success": {"type": "effect", "effects": [{"type": "remove_item", "item_id": "mayor_letter", "count": 1}, {"type": "set_flag", "flag": "gate_passed", "value": true}, {"type": "change_affinity", "npc_id": "guard_captain", "value": 20}, {"type": "complete_quest", "quest_id": "pass_the_gate", "method_used": "recommendation"}], "next_node_id": "letter_dialogue"}, "letter_dialogue": {"type": "narrative", "speaker": "守衛長", "text": "守衛長看著介紹信上的親筆簽名，臉色微變並挺直腰桿：「原來是老闆娘保薦的貴客！失敬，請立刻通行！」【解法二：以人脈與交情順利通關】", "next_node_id": "ending_letter"}, "ending_letter": {"type": "end", "end_type": "game_ending", "ending_id": "cleared_by_network", "ending_title": "貴人引薦：深受信賴的同袍"}, "inquire_gate": {"type": "narrative", "speaker": "守衛長", "text": "「近來外界頻生異常，鎮長下令嚴防流竄。要通過，要嘛繳納 80 金幣重稅登記，要嘛具備在地名望人士的親筆引薦，沒有第三條路！」", "next_node_id": "choice_gate"}, "end_normal": {"type": "end", "end_type": "return_to_exploration"}}}, "flow_innkeeper": {"id": "flow_innkeeper", "name": "旅店老闆娘對話", "nodes": {"start": {"type": "start", "next_node_id": "greet_inn"}, "greet_inn": {"type": "narrative", "speaker": "旅店老闆娘", "text": "「哎呀，瞧你一臉茫然的樣子，剛來小鎮吧？若是累了隨時能在這打尖歇歇腳。」", "next_node_id": "choice_inn"}, "choice_inn": {"type": "choice", "choices": [{"id": "ask_help", "label": "詢問是否需要幫忙（好感委託）", "condition": {"field": "flag.inn_help_done", "op": "!=", "value": true}, "next_node_id": "inn_quest_offer"}, {"id": "submit_herb", "label": "遞交採集到的 2 包【野草草藥】幫忙旅店", "condition": {"all": [{"field": "flag.inn_help_accepted", "op": "==", "value": true}, {"field": "flag.inn_help_done", "op": "!=", "value": true}, {"field": "item.wild_herb", "op": ">=", "value": 2}]}, "next_node_id": "inn_submit_herb"}, {"id": "brawler_event", "label": "調查角落鬧事的醉漢（特殊遭遇）", "condition": {"all": [{"field": "time_of_day", "op": "==", "value": "night"}, {"field": "flag.brawler_settled", "op": "!=", "value": true}]}, "next_node_id": "encounter_brawler"}, {"id": "leave_inn", "label": "只是隨便看看（離開）", "next_node_id": "end_inn"}]}, "inn_quest_offer": {"type": "effect", "effects": [{"type": "set_flag", "flag": "inn_help_accepted", "value": true}], "next_node_id": "inn_quest_dialogue"}, "inn_quest_dialogue": {"type": "narrative", "speaker": "旅店老闆娘", "text": "「近來鎮上藥材短缺，若你能去鎮郊工坊後山採集 2 包野草草藥給我，我便寫封引薦信，請守衛長為你行個方便！」", "next_node_id": "end_inn"}, "inn_submit_herb": {"type": "effect", "effects": [{"type": "remove_item", "item_id": "wild_herb", "count": 2}, {"type": "add_item", "item_id": "mayor_letter", "count": 1}, {"type": "change_affinity", "npc_id": "innkeeper", "value": 30}, {"type": "set_flag", "flag": "inn_help_done", "value": true}], "next_node_id": "inn_submit_dialogue"}, "inn_submit_dialogue": {"type": "narrative", "speaker": "旅店老闆娘", "text": "「太感謝了！這些草藥解了燃眉之急。這封《鎮長介紹信》你收著，守衛長看在我的面子上絕不敢刁難你！」", "next_node_id": "end_inn"}, "encounter_brawler": {"type": "narrative", "speaker": "醉酒挑釁者", "text": "一名酒氣熏天的醉漢搖搖晃晃撞上你：「你看什麼看？！新來的鄉巴佬，想找碴嗎？！」", "next_node_id": "choice_brawler"}, "choice_brawler": {"type": "choice", "choices": [{"id": "pacify_brawler", "label": "【口才安撫】運用魅力嘗試好言相勸（魅力檢定）", "next_node_id": "check_brawler_pacify"}, {"id": "fight_brawler", "label": "【正面迎戰】直接迎頭痛擊鬧事者（進入戰鬥）", "next_node_id": "combat_brawler"}]}, "check_brawler_pacify": {"type": "check", "stat": "charisma", "base_chance": 60, "stat_coeff": 3.0, "success_node_id": "brawler_pacified", "fail_node_id": "combat_brawler"}, "brawler_pacified": {"type": "effect", "effects": [{"type": "set_flag", "flag": "brawler_settled", "value": true}, {"type": "change_affinity", "npc_id": "innkeeper", "value": 15}, {"type": "modify_stat", "stat": "gold", "value": 20}], "next_node_id": "brawler_pacified_narrative"}, "brawler_pacified_narrative": {"type": "narrative", "speaker": "旅店老闆娘", "text": "你言辭懇切、不卑不亢地化解了紛爭，醉漢自討沒趣地嘟囔著坐下。老闆娘欣喜地塞給你 20 金幣以示酬謝！", "next_node_id": "end_inn"}, "combat_brawler": {"type": "combat", "enemy_id": "drunk_brawler", "win_node_id": "brawler_won", "lose_node_id": "end_inn", "escape_node_id": "end_inn"}, "brawler_won": {"type": "effect", "effects": [{"type": "set_flag", "flag": "brawler_settled", "value": true}, {"type": "modify_stat", "stat": "gold", "value": 15}], "next_node_id": "brawler_won_narrative"}, "brawler_won_narrative": {"type": "narrative", "speaker": "系統", "text": "你俐落地制伏了鬧事醉漢，贏得旅店內一陣叫好，從對方掉落的錢袋中取得了 15 金幣！", "next_node_id": "end_inn"}, "end_inn": {"type": "end", "end_type": "return_to_exploration"}}}, "flow_merchant": {"id": "flow_merchant", "name": "商人羅倫斯對話", "nodes": {"start": {"type": "start", "next_node_id": "greet_mer"}, "greet_mer": {"type": "narrative", "speaker": "熱心商人", "text": "「嘿！遠方的旅人，只要出得起價錢，這裡什麼都有。如果手頭緊，去工坊或後山打工採集也是賺錢的好門路。」", "next_node_id": "choice_mer"}, "choice_mer": {"type": "choice", "choices": [{"id": "ask_rumors", "label": "詢問關於世界異常與穿越的傳聞", "next_node_id": "mer_rumors"}, {"id": "leave_mer", "label": "多謝提醒，我先四處看看", "next_node_id": "end_mer"}]}, "mer_rumors": {"type": "narrative", "speaker": "熱心商人", "text": "「傳聞後山深處經常有奇異的藍光閃爍，老鐵匠奧古斯特似乎在研究那些發光的石頭。若你想弄明白，不妨去拜訪他。」", "next_node_id": "end_mer"}, "end_mer": {"type": "end", "end_type": "return_to_exploration"}}}, "flow_artisan": {"id": "flow_artisan", "name": "老工匠奧古斯特對話", "nodes": {"start": {"type": "start", "next_node_id": "greet_art"}, "greet_art": {"type": "narrative", "speaker": "老工匠", "text": "老工匠放下鐵鎚，打量著你手上的裝備：「年輕人，你的腳步聲沉穩，但眼中帶著不屬於這片土地的疑惑。」", "next_node_id": "choice_art"}, "choice_art": {"type": "choice", "choices": [{"id": "show_fragment", "label": "【展示碎片】拿出在後山發現的《未知碎片》請教", "condition": {"field": "item.unknown_fragment", "op": ">=", "value": 1}, "next_node_id": "art_fragment_revealed"}, {"id": "ask_secret_trail", "label": "詢問後山山道是否真有捷徑通往外界", "next_node_id": "art_trail_hint"}, {"id": "leave_art", "label": "不打擾您工作（離開）", "next_node_id": "end_art"}]}, "art_fragment_revealed": {"type": "effect", "effects": [{"type": "complete_quest", "quest_id": "anomaly_echoes", "method_used": "fragment_studied"}, {"type": "change_affinity", "npc_id": "artisan", "value": 40}, {"type": "modify_stat", "stat": "atk", "value": 3}], "next_node_id": "art_fragment_narrative"}, "art_fragment_narrative": {"type": "narrative", "speaker": "老工匠", "text": "奧古斯特雙手顫抖接過碎片：「這…這正是古書記載的『異世之樞』殘片！你果然是穿越時空壁壘而來的行者！老夫替你的武器銘刻古老符印（攻擊+3），祝你早日找到答案。」", "next_node_id": "end_art"}, "art_trail_hint": {"type": "narrative", "speaker": "老工匠", "text": "「後山密道隱蔽而危險，若你的敏捷或智力足夠識破山霧與碎石，確實能避開前方的關卡守衛直接出關。」", "next_node_id": "end_art"}, "end_art": {"type": "end", "end_type": "return_to_exploration"}}}, "flow_gather_mountain": {"id": "flow_gather_mountain", "name": "後山採集事件", "nodes": {"start": {"type": "start", "next_node_id": "random_gather_event"}, "random_gather_event": {"type": "random", "branches": [{"weight": 6, "next_node_id": "gather_normal"}, {"weight": 4, "next_node_id": "gather_beast_encounter"}]}, "gather_normal": {"type": "effect", "effects": [{"type": "add_item", "item_id": "wild_herb", "count": 1}], "next_node_id": "gather_normal_text"}, "gather_normal_text": {"type": "narrative", "text": "你在山崖邊細心搜尋，採集到了一株新鮮的【野草草藥】。", "next_node_id": "end_gather"}, "gather_beast_encounter": {"type": "narrative", "text": "正當你撥開樹叢時，一頭低吼的【後山兇惡野獸】猛然擋在眼前！", "next_node_id": "choice_beast"}, "choice_beast": {"type": "choice", "choices": [{"id": "distract_beast", "label": "【投擲口糧】丟出《行囊口糧》引開野獸注意力（避開戰鬥）", "condition": {"field": "item.travel_ration", "op": ">=", "value": 1}, "cost": {}, "next_node_id": "beast_distracted"}, {"id": "check_agility_beast", "label": "【靈巧繞道】利用敏捷身手迅速撤退（敏捷檢定）", "next_node_id": "check_beast_escape"}, {"id": "fight_beast", "label": "【正面迎戰】拔出武器與野獸搏鬥（戰鬥）", "next_node_id": "combat_beast_node"}]}, "beast_distracted": {"type": "effect", "effects": [{"type": "remove_item", "item_id": "travel_ration", "count": 1}, {"type": "add_item", "item_id": "wild_herb", "count": 1}], "next_node_id": "beast_distracted_text"}, "beast_distracted_text": {"type": "narrative", "text": "野獸被誘人的口糧吸引過去大嚼，你趁機採下草藥悄然脫身！", "next_node_id": "end_gather"}, "check_beast_escape": {"type": "check", "stat": "agility", "base_chance": 50, "stat_coeff": 3.0, "success_node_id": "beast_escaped", "fail_node_id": "combat_beast_node"}, "beast_escaped": {"type": "narrative", "text": "你縱身一躍躍上高處岩石，野獸撲了個空，你順利甩開追擊！", "next_node_id": "end_gather"}, "combat_beast_node": {"type": "combat", "enemy_id": "mountain_beast", "win_node_id": "beast_slain", "lose_node_id": "end_gather", "escape_node_id": "end_gather"}, "beast_slain": {"type": "effect", "effects": [{"type": "add_item", "item_id": "wild_herb", "count": 2}, {"type": "modify_stat", "stat": "gold", "value": 25}], "next_node_id": "beast_slain_text"}, "beast_slain_text": {"type": "narrative", "text": "兇惡的野獸哀號倒地，你在獸穴旁拾取了 25 金幣與 2 株草藥！", "next_node_id": "end_gather"}, "end_gather": {"type": "end", "end_type": "return_to_exploration"}}}, "flow_secret_trail": {"id": "flow_secret_trail", "name": "秘密山道探索", "nodes": {"start": {"type": "start", "next_node_id": "trail_desc"}, "trail_desc": {"type": "narrative", "text": "藤蔓與落石掩映之下，露出一條極為陡峭的裂隙小徑。冷風從幽暗的石壁縫隙吹來，似乎能直接繞過前方的守衛關卡。", "next_node_id": "choice_trail"}, "choice_trail": {"type": "choice", "choices": [{"id": "check_trail_intellect", "label": "【勘查路徑】運用智力分析石層結構與地圖（智力檢定）", "next_node_id": "check_trail_int"}, {"id": "check_trail_agility", "label": "【攀登穿越】憑藉矯健身手攀上險峻裂谷（敏捷檢定）", "next_node_id": "check_trail_agi"}, {"id": "leave_trail", "label": "太危險了，先退回工坊", "next_node_id": "end_trail"}]}, "check_trail_int": {"type": "check", "stat": "intellect", "base_chance": 50, "stat_coeff": 3.0, "success_node_id": "trail_success_effect", "fail_node_id": "trail_failed"}, "check_trail_agi": {"type": "check", "stat": "agility", "base_chance": 50, "stat_coeff": 3.0, "success_node_id": "trail_success_effect", "fail_node_id": "trail_failed"}, "trail_failed": {"type": "effect", "effects": [{"type": "modify_stat", "stat": "hp", "value": -15}], "next_node_id": "trail_failed_text"}, "trail_failed_text": {"type": "narrative", "text": "一塊風化岩石突然崩碎，你摔了下來受到 15 點擦傷！只得暫時退回。", "next_node_id": "end_trail"}, "trail_success_effect": {"type": "effect", "effects": [{"type": "add_item", "item_id": "unknown_fragment", "count": 1}, {"type": "set_flag", "flag": "gate_passed", "value": true}, {"type": "complete_quest", "quest_id": "pass_the_gate", "method_used": "secret_trail"}], "next_node_id": "trail_success_text"}, "trail_success_text": {"type": "narrative", "text": "你成功穿越了後山險隘！在裂谷深處的祭壇上，你發現並拾起了一枚散發幽光的【未知碎片】！前方豁然開朗，你已徹底繞過了守衛關卡！【解法三：環境調查密道潛越】", "next_node_id": "ending_trail"}, "ending_trail": {"type": "end", "end_type": "game_ending", "ending_id": "cleared_by_secret_trail", "ending_title": "暗道潛影：掌握祕辛的探索者"}, "end_trail": {"type": "end", "end_type": "return_to_exploration"}}}}}', N'admin', N'示範發布版本');
    END;

